def calculate_binary_search_trees(number):

    # Base case
    if number <= 1:
        return 1

    # Recursively call the function, summing the result
    total = 0
    for i in range(1, number + 1):
        total += calculate_binary_search_trees(i - 1) * calculate_binary_search_trees(number - i)
    return total

def sort_lexicographically(arr):

    n = len(arr) 
    for i in range(n):
        min_index = i
        for j in range(i + 1, n):
            if arr[min_index] > arr[j]:
                min_index = j
        arr[i], arr[min_index] = arr[min_index], arr[i]
    return arr

def contains(script, keywords):


    # The keyword must be the first item in a list.
    if type(script) != list or not script:
        return False

    if script[0] in keywords:
        return True

    # Iterate over all children.
    return any(contains(child, keywords) for child in script)

